{"summary":"实现互锁启动 FB：每个扫描周期计算上升沿（start 为 TRUE 且上一周期 start 为 FALSE），并更新上一周期 start 记忆；stop 为 TRUE 或 permit 为 FALSE 时立即清除 running 并优先于启动；仅当无清除条件且检测到上升沿时置位 running，因此 permit 恢复后保持按下的 start 不会重启。","code":"FUNCTION_BLOCK InterlockedStart
VAR_INPUT
  start : BOOL;
  stop : BOOL;
  permit : BOOL;
END_VAR
VAR_OUTPUT
  running : BOOL;
END_VAR
VAR
  prevStart : BOOL;
  startEdge : BOOL;
END_VAR

startEdge := start AND NOT prevStart;
prevStart := start;

IF stop OR NOT permit THEN
  running := FALSE;
ELSIF startEdge THEN
  running := TRUE;
END_IF;
END_FUNCTION_BLOCK","assumptions":[]}
